async function iaPedirPermisoMicrofonoUnaVez(){
  if(localStorage.getItem('ia_aspe_mic_ok') === '1') return true;
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return false;
  try{
    const stream = await navigator.mediaDevices.getUserMedia({audio:true});
    stream.getTracks().forEach(t=>t.stop());
    localStorage.setItem('ia_aspe_mic_ok','1');
    return true;
  }catch(e){
    return false;
  }
}

async function iaMicrofono(){
  const estado=document.getElementById('iaMicEstado');
  const ok=await iaPedirPermisoMicrofonoUnaVez();
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR){ estado.innerText='Tu navegador no soporta reconocimiento de voz. Probá con Chrome.'; return; }
  if(!ok){ estado.innerText='No se pudo activar el micrófono. Revisá permisos del navegador.'; return; }
  const rec=new SR();
  rec.lang='es-AR';
  rec.interimResults=true;
  rec.continuous=false;
  let finalText='';
  estado.innerText='Escuchando... hablá ahora.';
  rec.onresult=(ev)=>{
    let temp='';
    for(let i=ev.resultIndex;i<ev.results.length;i++){
      const t=ev.results[i][0].transcript;
      if(ev.results[i].isFinal) finalText += t + ' '; else temp += t;
    }
    document.getElementById('iaPregunta').value=(finalText+temp).trim();
  };
  rec.onerror=()=>{estado.innerText='No pude escuchar bien. Tocá el micrófono y probá de nuevo.'};
  rec.onend=()=>{estado.innerText='Texto detectado. Podés editarlo y después tocar Enviar.'};
  rec.start();
}

