function iaCrearLinkImagenesExterno(pregunta){
  const q = encodeURIComponent(("calefón ionizado " + pregunta).slice(0,160));
  return `<div class="ia-image-link-box"><b>¿Este es el problema que tenés?</b><br><a target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">Apretá aquí</a><br><small>El enlace es solo para ver imágenes de referencia cuando no hay foto del curso.</small></div>`;
}

function iaGetImageCandidates(chunk){
  if(!chunk || !chunk.imagen) return [];
  const img = String(chunk.imagen);
  const m = img.match(/^(.*_seg_)(\d+)(\.jpg)$/i);
  if(!m) return [img];
  const pref = m[1];
  const sec = parseInt(m[2],10);
  const ext = m[3];
  const nums = [];
  const add = n => { if(n >= 0 && !nums.includes(n)) nums.push(n); };
  add(sec);
  add(Math.round(sec/2)*2);      // si las fotos fueron sacadas cada 2 segundos
  add(Math.floor(sec/2)*2);
  add(Math.ceil(sec/2)*2);
  add(sec-1); add(sec+1); add(sec-2); add(sec+2); add(sec-3); add(sec+3);
  return nums.map(n => pref + n + ext);
}

function iaImgSiguiente(img){
  try{
    const list = JSON.parse(img.getAttribute('data-imgs') || '[]');
    let i = parseInt(img.getAttribute('data-i') || '0', 10) + 1;
    if(i < list.length){
      img.setAttribute('data-i', String(i));
      img.src = list[i];
    }else{
      img.parentElement.style.display='none';
    }
  }catch(e){ img.parentElement.style.display='none'; }
}

function iaImagenHTML(chunk){
  const imgs = iaGetImageCandidates(chunk);
  if(!imgs.length) return "";
  const data = iaEscape(JSON.stringify(imgs));
  const alt = iaEscape(`Imagen del curso ${chunk.clase} segundo ${chunk.segundo}`);
  return `<div class="ia-result-img"><img src="${iaEscape(imgs[0])}" data-imgs="${data}" data-i="0" alt="${alt}" onerror="iaImgSiguiente(this)"><small>Imagen del curso: ${iaEscape(chunk.clase)}, segundo aproximado ${iaEscape(chunk.segundo)}. Si esa captura exacta no existe, la AI prueba la más cercana.</small></div>`;
}

function iaFuentePDFHTML(chunk){
  if(!chunk || !String(chunk.clase||"").toLowerCase().includes("pdf")) return "";
  return `<div class="ia-source">📄 También hay información relacionada en los PDF/manuales del curso. Para verlo completo, entrá al apartado PDF y buscá el manual del modelo correspondiente.</div>`;
}

function iaRespuestaCursoHTML(pregunta){
  const diag = iaBuscarDiagnostico(pregunta);
  const resultados = iaBuscarCurso(pregunta, 6);
  const riesgo = iaEsRiesgoAlto(pregunta);

  if(!diag && resultados.length === 0){
    return {encontrado:false, html:"", resultados:[]};
  }

  let html = "";
  if(diag){
    html += `<p><b>Problema detectado:</b> ${iaEscape(diag.nombre)}</p><p>${iaEscape(diag.explicacion)}</p>`;
  }

  if(resultados.length){
    const r = resultados[0];
    html += `<p><b>Lo encontré en tu curso:</b><br>${iaEscape(r.clase)} — segundo aproximado ${iaEscape(r.segundo)}</p>`;
    html += iaImagenHTML(r);
    html += `<p><b>Explicación basada en el curso:</b><br>${iaEscape(iaLimpiarTextoCurso(r.texto))}</p>`;
    html += iaFuentePDFHTML(r);

    if(resultados.length > 1){
      html += `<details><summary>Ver más partes relacionadas del curso</summary>`;
      resultados.slice(1).forEach(x=>{
        html += `<div class="ia-extra"><b>${iaEscape(x.clase)}</b> — segundo ${iaEscape(x.segundo)}${iaImagenHTML(x)}<br>${iaEscape(iaLimpiarTextoCurso(x.texto))}${iaFuentePDFHTML(x)}</div>`;
      });
      html += `</details>`;
    }
  }

  if(riesgo){
    html += `<div class="ia-warning"><b>Seguridad:</b> si aparece olor fuerte, combustión rara, llama de color anormal, retorno de gases o el equipo se apaga por sensores, no anules sensores ni sigas forzando el funcionamiento. Revisalo con un profesional matriculado.</div>`;
  }else{
    html += `<div class="ia-warning"><b>Nota:</b> respuesta educativa basada en tu curso y manuales. La intervención interna debe hacerla una persona capacitada.</div>`;
  }
  return {encontrado:true, html, resultados};
}

async function iaResponderCompleto(pregunta){
  if(!iaEsTemaPermitido(pregunta)){
    return `<p><b>Solo puedo responder sobre calefones ionizados y el contenido del curso.</b></p><p>Escribí el síntoma: prende y se apaga, hace chispa pero no prende, no enciende, calienta poco, error en display, ionización, caudal, sarro, placa, quemador o sensor.</p>`;
  }

  const curso = iaRespuestaCursoHTML(pregunta);
  if(curso.encontrado){
    return curso.html;
  }

  // Si no está en subtítulos/PDF/base local, recién ahí consulta Gemini.
  let geminiHTML = "";
  try{
    const respuesta = await iaConsultarGemini(pregunta);
    geminiHTML = `<p><b>No encontré esa solución exacta en los videos, subtítulos o PDFs cargados.</b></p><div class="ia-gemini-box"><b>Información recopilada para calefones ionizados:</b><br>${iaEscape(respuesta).replace(/\n/g,'<br>')}</div>`;
  }catch(e){
    geminiHTML = `<p><b>No encontré esa solución exacta en los videos, subtítulos o PDFs cargados.</b></p><p>No pude consultar Gemini en este momento. Puede ser por permisos de API, internet o CORS del navegador.</p>`;
  }
  return geminiHTML + iaCrearLinkImagenesExterno(pregunta);
}

