function iaEsTemaNoElectrico(pregunta){
  const p = iaNormalizar(pregunta);
  const bloqueadas = [
    "olor", "perdida", "pérdida", "caneria", "cañeria", "cañería", "plomeria", "plomería",
    "instalacion", "instalación", "matriculado", "monoxido", "monóxido", "chimenea", "ventilacion",
    "ventilación", "tiraje", "tiro balanceado", "tiro natural", "tiro forzado", "conducto", "combustion", "combustión",
    "llama amarilla", "llama naranja", "llama roja", "explosion", "explosión", "quemador explota", "valvula de combustible"
  ];
  return bloqueadas.some(w => p.includes(iaNormalizar(w)));
}

function iaEsTemaPermitido(pregunta){
  const p = iaNormalizar(pregunta);
  const permitidas = [
    "calefon", "calefon ionizado", "ionizado", "ionizacion", "ionización", "chispa", "electrodo",
    "bujia", "bujía", "sensor", "sensor de ionizacion", "placa", "placa electronica", "display", "codigo",
    "código", "error", "caudal", "sensor de caudal", "micro switch", "microswitch", "serpentina", "sarro",
    "intercambiador", "orbis", "eurotrend", "aspe", "calienta", "enciende", "prende", "apaga", "agua caliente",
    "pilas", "fuente", "transformador", "chispero", "cable", "cableado", "conector", "conectores", "temperatura",
    "sobrecalentamiento", "termostato", "modulo", "módulo", "electrico", "eléctrico", "electronico", "electrónico"
  ];
  return permitidas.some(w => p.includes(iaNormalizar(w)));
}

function iaDiagnosticoElectrico(pregunta){
  const p = iaNormalizar(pregunta);
  const d = [
    {nombre:"No enciende", claves:["no enciende","no prende","no arranca","no hace nada"], explicacion:"Puede estar relacionado con pilas/fuente, módulo de encendido, cableado, conectores, micro switch, sensor de caudal o placa electrónica. Revisá visualmente conexiones externas, estado de pilas/fuente y si aparece algún código de error."},
    {nombre:"Hace chispa pero no prende", claves:["chispa pero no prende","hace chispa","chispea","no prende con chispa"], explicacion:"Puede estar relacionado con electrodo de encendido, bujía/electrodo mal posicionado, cable de alta flojo, módulo/chispero o placa electrónica. La AI se enfoca en la parte eléctrica/electrónica del diagnóstico."},
    {nombre:"Prende y se apaga", claves:["prende y se apaga","enciende y se apaga","corta rapido","corta rápido","se apaga","no detecta llama"], explicacion:"En calefones ionizados suele relacionarse con detección por ionización: electrodo/sensor de ionización, cable del sensor, masa/conexión, módulo de control o placa electrónica. El equipo corta cuando la electrónica no confirma correctamente la señal."},
    {nombre:"No detecta llama / ionización", claves:["no detecta llama","ionizacion","ionización","sensor de ionizacion","sensor de ionización"], explicacion:"La detección por ionización usa el electrodo/sensor y la placa para confirmar señal. Puede fallar por sensor sucio/mal ubicado, cable flojo, mala masa, conector sulfatado o placa electrónica."},
    {nombre:"Error en display", claves:["error","display","codigo","código","pantalla"], explicacion:"Un error en display puede estar ligado a placa electrónica, sensor de temperatura, sensor de caudal, sobretemperatura, ionización o alimentación. Conviene identificar el código y cruzarlo con el manual/PDF del modelo."},
    {nombre:"Calienta poco", claves:["calienta poco","sale tibia","poca agua caliente","no calienta"], explicacion:"Desde la parte eléctrica/electrónica puede relacionarse con sensor de temperatura, sensor de caudal, placa, regulación electrónica o lectura incorrecta. Si la causa es hidráulica o de instalación, esta AI no la desarrolla."},
    {nombre:"Problema de caudal", claves:["caudal","sensor de caudal","micro switch","microswitch"], explicacion:"Puede estar relacionado con sensor de caudal, micro switch, conectores o placa. El sistema necesita detectar circulación para habilitar el encendido."},
    {nombre:"Problema de placa", claves:["placa","placa electronica","placa electrónica","modulo","módulo"], explicacion:"La placa recibe señales de sensores, maneja el encendido y valida la ionización. Fallas típicas pueden verse como falta de chispa, corte rápido, error en display o respuesta irregular."}
  ];
  return d.find(x => x.claves.some(c => p.includes(iaNormalizar(c))));
}

function iaTextoEsUtilElectrico(t){
  const n = iaNormalizar(t || "");
  const electricos = ["electrodo","ionizacion","ionización","sensor","placa","electrica","eléctrica","electronica","electrónica","chispa","encendido","bujia","bujía","display","codigo","código","caudal","micro","cable","conector","temperatura","termostato","sobrecalentamiento","pilas","fuente","modulo","módulo"];
  return electricos.some(w => n.includes(iaNormalizar(w)));
}

function iaBuscarCursoElectrico(pregunta, limite=6){
  let res = iaBuscarCurso(pregunta, Math.max(30, limite * 5));
  res = res.filter(x => iaTextoEsUtilElectrico((x.texto||"") + " " + (x.keywords||[]).join(" ")));
  if(!res.length) res = iaBuscarCurso(pregunta, limite);
  return res.slice(0, limite);
}

function iaLimpiarTextoCurso(texto){
  let t = String(texto || "").replace(/\s+/g, " ").trim();
  t = t.replace(/\bgas\b/gi, "sistema del equipo");
  t = t.replace(/\bcombusti[oó]n\b/gi, "funcionamiento del equipo");
  t = t.replace(/\bllama\b/gi, "señal de ionización");
  t = t.replace(/\bquemador\b/gi, "sector de encendido");
  if(/puentear|puenteamos|anular|anularse|cablecito|patitas/i.test(t)){
    return "En esta parte del curso se habla del circuito de sensores, corte de seguridad y diagnóstico eléctrico. La AI no recomienda anular sensores ni hacer puentes: se debe revisar el componente eléctrico correspondiente y confirmar con el manual del modelo.";
  }
  return t;
}

function iaCrearLinkImagenesExterno(pregunta){
  const q = encodeURIComponent(("calefón ionizado parte eléctrica " + pregunta).slice(0,160));
  return `<div class="ia-image-link-box"><b>¿Este es el problema que tenés?</b><br><a target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">Apretá aquí</a><br><small>Este enlace se muestra solo como referencia visual cuando no hay una imagen clara del curso.</small></div>`;
}

function iaGetImageCandidates(chunk){
  if(!chunk || !chunk.imagen) return [];
  const img = String(chunk.imagen);
  const m = img.match(/^(.*_seg_)(\d+)(\.jpg)$/i);
  if(!m) return [img];
  const pref = m[1], sec = parseInt(m[2],10), ext = m[3];
  const max = IA_ASPE_IMAGE_LIMITS[pref];
  const nums = [];
  const add = n => {
    n = Math.round(n);
    if(n < 0) return;
    if(typeof max === "number" && n > max) return;
    if(!nums.includes(n)) nums.push(n);
  };
  add(sec); add(Math.round(sec/2)*2); add(Math.floor(sec/2)*2); add(Math.ceil(sec/2)*2);
  for(let d=1; d<=12; d++){ add(sec-d); add(sec+d); }
  if(typeof max === "number"){ add(Math.min(sec, max)); add(max); }
  return nums.map(n => pref + n + ext);
}

function iaImagenHTML(chunk){
  const imgs = iaGetImageCandidates(chunk);
  if(!imgs.length) return "";
  const data = iaEscape(JSON.stringify(imgs));
  const alt = iaEscape(`Imagen del curso ${chunk.clase} segundo ${chunk.segundo}`);
  return `<div class="ia-result-img"><img src="${iaEscape(imgs[0])}" data-imgs="${data}" data-i="0" alt="${alt}" onerror="iaImgSiguiente(this)"><small>Imagen del curso: ${iaEscape(chunk.clase)}, segundo aproximado ${iaEscape(chunk.segundo)}</small></div>`;
}

function iaExplicacionElectrica(pregunta, diag, chunk){
  const p = iaNormalizar(pregunta);
  if(diag) return diag.explicacion;
  if(p.includes("ionizacion") || p.includes("ionización")) return "La ionización es la señal que usa la electrónica para confirmar que el calefón detectó correctamente el encendido. En el curso se relaciona con electrodo/sensor, cableado, masa/conexión y placa electrónica.";
  if(p.includes("electrodo") || p.includes("bujia") || p.includes("bujía")) return "El electrodo participa en el encendido y/o detección. Una falla puede provocar falta de chispa, chispa débil, corte rápido o ausencia de señal hacia la placa.";
  if(p.includes("placa")) return "La placa electrónica coordina encendido, sensores, corte y lectura de señales. Si recibe señales incorrectas o tiene falla, puede generar errores, cortes o falta de encendido.";
  if(chunk) return iaLimpiarTextoCurso(chunk.texto);
  return "La consulta está relacionada con componentes eléctricos/electrónicos del calefón ionizado. Conviene revisar el componente señalado, su cableado, conectores y la clase/PDF indicada por la AI.";
}

