function iaRespuestaCursoHTML(pregunta){
  if(iaEsTemaNoElectrico(pregunta)){
    return {encontrado:true, html:`<p><b>Esta AI está configurada solo para la parte eléctrica/electrónica del calefón ionizado.</b></p><p>Preguntame por electrodo, ionización, chispa, placa electrónica, sensor de caudal, display, pilas/fuente, cableado, conectores, sensores o códigos de error.</p>`, resultados:[]};
  }
  const diag = iaDiagnosticoElectrico(pregunta);
  const resultados = iaBuscarCursoElectrico(pregunta, 6);
  if(!diag && resultados.length === 0) return {encontrado:false, html:"", resultados:[]};
  let html = "";
  if(diag) html += `<p><b>Problema detectado:</b> ${iaEscape(diag.nombre)}</p>`;
  const r = resultados[0];
  if(r){
    html += `<p><b>Lo encontré en tu curso:</b><br>${iaEscape(r.clase)} — segundo aproximado ${iaEscape(r.segundo)}</p>`;
    html += iaImagenHTML(r);
    html += `<p><b>Explicación basada en el curso:</b><br>${iaEscape(iaExplicacionElectrica(pregunta, diag, r))}</p>`;
    html += `<p><b>Texto relacionado del subtítulo:</b><br>${iaEscape(iaLimpiarTextoCurso(r.texto))}</p>`;
    html += iaFuentePDFHTML(r);
    if(resultados.length > 1){
      html += `<details><summary>Ver más partes relacionadas del curso</summary>`;
      resultados.slice(1).forEach(x=>{
        html += `<div class="ia-extra"><b>${iaEscape(x.clase)}</b> — segundo ${iaEscape(x.segundo)}${iaImagenHTML(x)}<br>${iaEscape(iaLimpiarTextoCurso(x.texto))}${iaFuentePDFHTML(x)}</div>`;
      });
      html += `</details>`;
    }
  }else{
    html += `<p><b>Explicación:</b><br>${iaEscape(iaExplicacionElectrica(pregunta, diag, null))}</p>`;
  }
  html += `<div class="ia-warning"><b>Alcance de la AI:</b> esta respuesta es educativa y se limita a diagnóstico eléctrico/electrónico del curso: sensores, placa, electrodo, chispa, display, cableado, fuente y señales.</div>`;
  return {encontrado:true, html, resultados};
}

async function iaConsultarGemini(pregunta){
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${IA_ASPE_GEMINI_MODEL}:generateContent?key=${IA_ASPE_GEMINI_API_KEY}`;
  const prompt = `Sos la AI del Curso Aspe. Respondé SOLO sobre la parte eléctrica y electrónica de calefones ionizados: placa electrónica, electrodo, sensor de ionización, bujía, chispero, módulo de encendido, pilas/fuente, cableado, conectores, display, sensores de temperatura y sensor de caudal. No expliques plomería, instalación, cañerías, combustible, ventilación ni combustión. Si la pregunta no es eléctrica/electrónica, decí que la AI solo cubre parte eléctrica/electrónica. Usuario: ${pregunta}. Da posible causa, explicación simple, qué componente puede estar asociado y palabras para buscar una imagen del componente.`;
  const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({contents:[{parts:[{text:prompt}]}]})});
  if(!res.ok) throw new Error('Gemini HTTP '+res.status);
  const data = await res.json();
  return data?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || 'No hubo respuesta.';
}

async function iaResponderCompleto(pregunta){
  if(!iaEsTemaPermitido(pregunta)){
    return `<p><b>Solo puedo responder sobre calefones ionizados y, principalmente, sobre su parte eléctrica/electrónica.</b></p><p>Ejemplos: prende y se apaga, hace chispa pero no prende, no enciende, error en display, electrodo, sensor de ionización, placa electrónica, pilas/fuente, sensor de caudal o cableado.</p>`;
  }
  const curso = iaRespuestaCursoHTML(pregunta);
  if(curso.encontrado) return curso.html;
  let geminiHTML = "";
  try{
    const respuesta = await iaConsultarGemini(pregunta);
    geminiHTML = `<p><b>No encontré esa solución exacta en los videos, subtítulos o PDFs cargados.</b></p><div class="ia-gemini-box"><b>Información recopilada para la parte eléctrica/electrónica de calefones ionizados:</b><br>${iaEscape(respuesta).replace(/\n/g,'<br>')}</div>`;
  }catch(e){
    geminiHTML = `<p><b>No encontré esa solución exacta en los videos, subtítulos o PDFs cargados.</b></p><p>No pude consultar Gemini en este momento. Puede ser por permisos de API, internet o CORS del navegador.</p>`;
  }
  return geminiHTML + iaCrearLinkImagenesExterno(pregunta);
}

