const IA_ASPE_GEMINI_MODEL_V5 = "gemini-2.0-flash";

function iaEsTemaPermitidoV5(pregunta){
  const p = iaNormalizar(pregunta);
  const base = [
    "calefon", "calefón", "ionizado", "electrodo", "ionizacion", "ionización", "chispa", "chispero", "bujia", "bujía",
    "placa", "plaqueta", "modulo", "módulo", "encendido", "sensor", "caudal", "temperatura", "sobrecalentamiento",
    "display", "error", "codigo", "código", "pilas", "bateria", "batería", "fuente", "cable", "cableado", "conector", "conectores",
    "prende", "enciende", "apaga", "corta", "no prende", "no enciende", "orbis", "eurotrend", "aspe"
  ].map(iaNormalizar);
  return base.some(w => p.includes(w));
}

function iaEsTemaNoElectricoV5(pregunta){
  const p = iaNormalizar(pregunta);
  const bloqueados = ["cañeria", "cañería", "instalacion de gas", "instalación de gas", "plomeria", "plomería", "matriculado", "perdida de gas", "pérdida de gas", "olor a gas", "garrafa", "regulador de gas", "conducto de gas"];
  return bloqueados.some(w => p.includes(iaNormalizar(w)));
}

function iaCrearLinkImagenesExterno(pregunta){
  const q = encodeURIComponent("calefón ionizado parte eléctrica " + pregunta);
  return `<div class="ia-google-box"><b>¿Este es el problema que tenés?</b><br><a class="ia-img-link" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">Apretá aquí</a></div>`;
}

