async function iaConsultarGemini(pregunta){
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${IA_ASPE_GEMINI_MODEL_V5}:generateContent?key=${IA_ASPE_GEMINI_API_KEY}`;
  const prompt = `Sos la AI del Curso Aspe. Respondé en español y SOLO sobre calefones ionizados, enfocándote en parte eléctrica/electrónica: placa electrónica, electrodo de encendido, electrodo/sensor de ionización, chispero, módulo de encendido, pilas/fuente, cableado, conectores, display, sensores eléctricos, sensor de caudal, sensor de temperatura y fallas de encendido/corte. No expliques plomería, instalación de gas, cañerías ni reparaciones de gas. Si el tema no corresponde, respondé que la AI solo cubre calefones ionizados eléctricos/electrónicos.\n\nPregunta del alumno: ${pregunta}\n\nDá una respuesta práctica con: 1) problema probable, 2) explicación simple, 3) componentes eléctricos/electrónicos a revisar visualmente, 4) qué palabras usar para identificar una imagen del problema. No digas que sos Google. No inventes pasos peligrosos.`;

  const bodyConBusqueda = {
    contents:[{parts:[{text:prompt}]}],
    tools:[{google_search:{}}]
  };

  try{
    const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(bodyConBusqueda)});
    if(!res.ok) throw new Error('Gemini grounding HTTP '+res.status);
    const data = await res.json();
    const txt = data?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || '';
    if(txt.trim()) return txt;
  }catch(e){
    // Reintento sin búsqueda web: sirve si la key/modelo no tiene grounding activo.
  }

  const res2 = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({contents:[{parts:[{text:prompt}]}]})});
  if(!res2.ok) throw new Error('Gemini HTTP '+res2.status);
  const data2 = await res2.json();
  return data2?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || 'No hubo respuesta.';
}

