function iaImagenHTML(chunk){
  if(!chunk || !chunk.imagen) return '';
  return `<div class="ia-result-img"><img src="${iaEscape(chunk.imagen)}" alt="Imagen del curso" onerror="this.parentElement.style.display='none'"><small>Imagen del curso: ${iaEscape(chunk.clase)} — segundo ${iaEscape(chunk.segundo)}</small></div>`;
}

function iaTextoCursoResumen(resultados){
  if(!resultados || !resultados.length) return 'No se encontró texto directo del curso para esta consulta.';
  return resultados.slice(0,4).map((r,i)=>`Parte ${i+1}: ${r.clase}, segundo ${r.segundo}. Texto: ${iaLimpiarTextoCurso(r.texto)}`).join('\n');
}

function iaDiagnosticoCliente(pregunta, diag, resultados){
  const p = iaNormalizar(pregunta);
  if(diag && diag.nombre) return diag.nombre;
  if(p.includes('chispa')) return 'Falla de encendido o chispa';
  if(p.includes('apaga') || p.includes('corta')) return 'Corte por detección de llama / ionización';
  if(p.includes('no enciende') || p.includes('no prende')) return 'No enciende';
  if(p.includes('error') || p.includes('codigo') || p.includes('pantalla') || p.includes('display')) return 'Código o error en pantalla';
  if(p.includes('placa') || p.includes('plaqueta')) return 'Placa electrónica';
  if(p.includes('sensor')) return 'Sensor eléctrico/electrónico';
  if(resultados && resultados[0]) return resultados[0].clase;
  return 'Consulta sobre calefón ionizado';
}

function iaHerramientasSugeridas(pregunta){
  const p = iaNormalizar(pregunta);
  const herramientas = ['manual del modelo', 'linterna', 'celular para sacar foto del componente', 'paño seco', 'tester/multímetro para mediciones básicas si sabés usarlo'];
  if(p.includes('pila') || p.includes('bateria') || p.includes('fuente')) herramientas.push('pilas nuevas o fuente compatible del equipo');
  if(p.includes('cable') || p.includes('conector')) herramientas.push('pinza pequeña aislada para revisar conectores visibles sin forzar');
  if(p.includes('electrodo') || p.includes('ionizacion') || p.includes('chispa')) herramientas.push('cepillo suave para limpieza superficial externa del electrodo si el equipo está apagado y frío');
  return herramientas;
}

async function iaConsultarGemini(pregunta, contextoCurso=''){
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${IA_ASPE_GEMINI_MODEL_V5}:generateContent?key=${IA_ASPE_GEMINI_API_KEY}`;
  const contexto = iaContextoConversacion();
  const prompt = `Sos la AI Aspe del curso de calefones ionizados. Respondé SIEMPRE en español, claro y para un cliente/alumno.

REGLAS:
- Respondé solo sobre calefones ionizados y su parte eléctrica/electrónica.
- Enfocate en electrodo de encendido, sensor/electrodo de ionización, chispero, módulo de encendido, placa electrónica, pilas/fuente, cableado, conectores, pantalla/códigos, sensores eléctricos, sensor de caudal y sensor de temperatura.
- No enseñes plomería ni instalación/reparación de gas. Si aparece algo de gas, decí que eso no lo cubre la AI y que debe verlo un profesional.
- No digas "Google". Podés usar información general de la web/modelo si está disponible.
- Dá explicación útil y coherente, no una respuesta corta.
- Incluí herramientas útiles solo para revisión visual/electrónica básica.
- No inventes el contenido del curso: si usás el curso, decí "En tu curso aparece relacionado con...".
- Cerrá con 2 o 3 preguntas para seguir la conversación.

CONVERSACIÓN ANTERIOR:
${contexto || 'No hay conversación anterior.'}

INFORMACIÓN ENCONTRADA EN EL CURSO/PDF/SRT:
${contextoCurso || 'No se encontró información directa en el curso para esta consulta.'}

PREGUNTA ACTUAL DEL ALUMNO:
${pregunta}

Formato de respuesta:
1) Qué puede estar pasando.
2) Explicación simple.
3) Qué mirar sin meterse con plomería/gas.
4) Herramientas útiles.
5) Dónde mirar en el curso si hay información.
6) Preguntas para seguir diagnosticando.`;

  const bodyConBusqueda = {
    contents:[{parts:[{text:prompt}]}],
    tools:[{google_search:{}}]
  };

  try{
    const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(bodyConBusqueda)});
    if(!res.ok) throw new Error('Gemini grounding HTTP '+res.status);
    const data = await res.json();
    const txt = data?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || '';
    if(txt.trim()) return txt;
  }catch(e){
    // Reintento sin búsqueda web por si el modelo o la key no tienen grounding activo.
  }

  const res2 = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({contents:[{parts:[{text:prompt}]}]})});
  if(!res2.ok) throw new Error('Gemini HTTP '+res2.status);
  const data2 = await res2.json();
  return data2?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || 'No hubo respuesta.';
}

function iaRespuestaCursoBaseV6(pregunta){
  const diag = iaDiagnosticoElectrico(pregunta);
  const resultados = iaBuscarCursoElectrico(pregunta, 6);
  const herramientas = iaHerramientasSugeridas(pregunta);
  let html = '';

  if(diag || resultados.length){
    html += `<span class="ia-course-tag">Encontrado en el curso</span>`;
    html += `<p><b>Problema detectado:</b> ${iaEscape(iaDiagnosticoCliente(pregunta, diag, resultados))}</p>`;
    if(resultados[0]){
      const r = resultados[0];
      html += `<p><b>En tu curso aparece relacionado con:</b><br>${iaEscape(r.clase)} — segundo aproximado ${iaEscape(r.segundo)}</p>`;
      html += iaImagenHTML(r);
      html += `<p><b>Explicación desde tu curso:</b><br>${iaEscape(iaExplicacionElectrica(pregunta, diag, r))}</p>`;
      html += `<p><b>Frase/texto encontrado:</b><br>${iaEscape(iaLimpiarTextoCurso(r.texto))}</p>`;
      html += iaFuentePDFHTML(r);
      if(resultados.length > 1){
        html += `<details><summary>Más partes del curso relacionadas</summary>`;
        resultados.slice(1).forEach(x=>{
          html += `<div class="ia-extra"><b>${iaEscape(x.clase)}</b> — segundo ${iaEscape(x.segundo)}${iaImagenHTML(x)}<br>${iaEscape(iaLimpiarTextoCurso(x.texto))}${iaFuentePDFHTML(x)}</div>`;
        });
        html += `</details>`;
      }
    }else if(diag){
      html += `<p><b>Explicación desde la base del curso:</b><br>${iaEscape(iaExplicacionElectrica(pregunta, diag, null))}</p>`;
    }
    html += `<p><b>Herramientas útiles para revisar la parte eléctrica/electrónica:</b><br>${herramientas.map(iaEscape).join(', ')}.</p>`;
  }
  return { html, resultados, contextoCurso: iaTextoCursoResumen(resultados), encontrado: !!(diag || resultados.length) };
}

async function iaResponderCompleto(pregunta){
  if(!iaEsTemaPermitidoV6(pregunta)){
    return `<p><b>Esta AI solo responde sobre calefones ionizados.</b></p><p>Podés preguntarme por encendido, chispa, electrodo, ionización, placa electrónica, pilas/fuente, sensores, cableado, conectores, pantalla/códigos o fallas de corte.</p>`;
  }
  if(iaEsTemaSoloGasOPlomeriaV6(pregunta)){
    return `<p><b>Eso no corresponde a esta AI.</b></p><p>Este asistente está armado para la parte eléctrica/electrónica del calefón ionizado. No explica plomería ni trabajos de gas.</p>`;
  }

  const curso = iaRespuestaCursoBaseV6(pregunta);
  let html = '';
  if(curso.encontrado){
    html += curso.html;
  }else{
    html += `<p><b>No encontré esa falla exacta en los videos/PDF/subtítulos cargados.</b></p>`;
  }

  try{
    const respuestaGemini = await iaConsultarGemini(pregunta, curso.contextoCurso);
    html += `<div class="ia-gemini-box"><b>Explicación ampliada:</b><br>${iaEscape(respuestaGemini).replace(/\n/g,'<br>')}</div>`;
  }catch(e){
    html += `<div class="ia-gemini-box"><b>Explicación ampliada no disponible ahora.</b><br>No pude consultar Gemini desde el navegador. Puede ser API key, permisos, internet, CORS o modelo sin búsqueda habilitada.</div>`;
  }

  // Si no hay imagen del curso relacionada, dejo acceso visual externo.
  const tieneImagenCurso = curso.resultados && curso.resultados.some(r=>r.imagen);
  if(!tieneImagenCurso){
    html += iaCrearLinkImagenesExterno(pregunta);
  }

  html += `<div class="ia-warning ia-warning-small"><b>Nota:</b> respuesta educativa enfocada en diagnóstico eléctrico/electrónico del calefón ionizado. No cubre plomería ni trabajos de gas.</div>`;
  return html;
}

async function iaEnviar(){
  const input=document.getElementById('iaPregunta');
  const pregunta=input.value.trim();
  if(!pregunta) return;
  IA_ASPE_CHAT_HISTORY.push({rol:'Alumno', texto:pregunta});
  iaAgregar(`<b>Alumno:</b> ${iaEscape(pregunta)}`, 'user');
  input.value = '';
  iaAgregar(`<b>AI Aspe:</b><br>Analizando tu curso y ampliando la explicación...`, 'bot');
  const html = await iaResponderCompleto(pregunta);
  IA_ASPE_CHAT_HISTORY.push({rol:'AI Aspe', texto:html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,1200)});
  iaAgregar(`<b>AI Aspe:</b><br>${html}`, 'bot');
}

async function iaBuscarGeminiDesdeInput(){
  const input=document.getElementById('iaPregunta');
  const pregunta=input.value.trim();
  if(!pregunta){ alert('Escribí primero el problema.'); return; }
  if(!iaEsTemaPermitidoV6(pregunta)){ iaAgregar('<b>AI Aspe:</b> Solo puedo buscar sobre calefones ionizados y parte eléctrica/electrónica.', 'bot'); return; }
  IA_ASPE_CHAT_HISTORY.push({rol:'Alumno', texto:pregunta});
  iaAgregar(`<b>Alumno:</b> ${iaEscape(pregunta)}`, 'user');
  input.value = '';
  try{
    const curso = iaRespuestaCursoBaseV6(pregunta);
    const respuesta = await iaConsultarGemini(pregunta, curso.contextoCurso);
    const html = `<div class="ia-gemini-box"><b>Explicación ampliada:</b><br>${iaEscape(respuesta).replace(/\n/g,'<br>')}</div>${curso.resultados?.some(r=>r.imagen) ? '' : iaCrearLinkImagenesExterno(pregunta)}`;
    IA_ASPE_CHAT_HISTORY.push({rol:'AI Aspe', texto:html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,1200)});
    iaAgregar(`<b>AI Aspe:</b>${html}`, 'bot');
  }catch(e){
    iaAgregar(`<b>No pude completar la consulta externa.</b><br>Puede ser API key, permisos, internet, CORS o modelo sin búsqueda habilitada.${iaCrearLinkImagenesExterno(pregunta)}`, 'bot');
  }
}

