/* =========================
   AI ASPE V7 - curso + Gemini sin errores visibles
   - Siempre intenta combinar curso + Gemini.
   - Si Gemini falla, responde igual con el curso/base local.
   - Si hay foto del curso, la muestra chica.
   - Si no hay foto del curso, muestra botón "Apretá aquí" a imágenes.
========================= */

const IA_ASPE_V7_MODELOS = ["gemini-1.5-flash", "gemini-2.0-flash", "gemini-2.0-flash-lite"];

function iaEsConsultaCalefonV7(pregunta){
  const p = iaNormalizar(pregunta || '');
  const claves = [
    'calefon','calefón','ionizado','ionizacion','ionización','chispa','electrodo','sensor','placa','electronica','electrónica',
    'display','pantalla','codigo','código','error','enciende','prende','apaga','corta','pilas','fuente','cable','conector',
    'caudal','temperatura','termostato','micro switch','microswitch','bujia','bujía','chispero','módulo','modulo','orbis','eurotrend','aspe'
  ];
  return claves.some(c => p.includes(iaNormalizar(c)));
}

function iaPreguntaEsConceptualV7(pregunta){
  const p = iaNormalizar(pregunta || '');
  return p.includes('que es') || p.includes('qué es') || p.includes('explicame') || p.includes('explica') || p.includes('diferencia') || p.includes('como funciona') || p.includes('cómo funciona');
}

function iaBuscarCursoV7(pregunta, limite=6){
  let resultados = iaBuscarCursoElectrico(pregunta, limite);

  // Para preguntas generales como "qué es un calefón ionizado", forzamos la introducción
  // y diferencia si el buscador anterior quedó demasiado limitado.
  if((!resultados || !resultados.length) && iaPreguntaEsConceptualV7(pregunta)){
    resultados = iaBuscarCurso(pregunta + ' calefón ionizado introducción diferencia funcionamiento ionización', limite);
  }

  // Si igual no encontró, busco por palabras base del tema.
  if(!resultados || !resultados.length){
    resultados = iaBuscarCurso('calefón ionizado electrodo ionización encendido placa sensor', limite);
  }

  return (resultados || []).slice(0, limite);
}

function iaLimpiarPreguntaParaImagenesV7(pregunta){
  let q = iaNormalizar(pregunta || '');
  q = q.replace(/explicame|explica|que es|qué es|mi calefon|mi calefón|tengo|problema|por favor|del curso|curso/g, ' ');
  q = q.replace(/\s+/g, ' ').trim();
  if(!q) q = 'calefón ionizado componentes eléctricos';
  if(!q.includes('calefon') && !q.includes('calefón')) q = 'calefón ionizado ' + q;
  q = q.replace('calefon', 'calefón');
  return q;
}

function iaCrearLinkImagenesExterno(pregunta){
  const consulta = iaLimpiarPreguntaParaImagenesV7(pregunta);
  const q = encodeURIComponent(consulta);
  return `<div class="ia-google-box"><b>¿Este es el problema que tenés?</b><br><a class="ia-img-link" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">Apretá aquí</a><br><small>Se abre solo una búsqueda de imágenes de referencia cuando no hay imagen clara en el curso.</small></div>`;
}

function iaTextoCursoParaGeminiV7(resultados){
  if(!resultados || !resultados.length) return 'No hay coincidencia exacta en el curso cargado.';
  return resultados.slice(0,5).map((r,i)=>{
    return `Coincidencia ${i+1}: ${r.clase}, segundo ${r.segundo}. Texto del curso: ${iaLimpiarTextoCurso(r.texto)}`;
  }).join('\n');
}

function iaExplicacionLocalV7(pregunta, diag, resultados){
  const p = iaNormalizar(pregunta || '');
  const r = resultados && resultados[0];

  if(iaPreguntaEsConceptualV7(pregunta) && (p.includes('ionizado') || p.includes('calefon'))){
    return `Un calefón ionizado es un calefón con encendido y control electrónico. A diferencia de uno tradicional con piloto permanente, usa componentes eléctricos como módulo de encendido, electrodo de chispa, sensor/electrodo de ionización, placa, sensores y conectores para iniciar el encendido y confirmar que el funcionamiento sea correcto. En tu curso esto aparece relacionado con la introducción y con la detección de llama por ionización.`;
  }
  if(diag && diag.explicacion) return diag.explicacion;
  if(p.includes('prende') && p.includes('apaga')) return 'Cuando prende y se apaga, lo más común en la parte eléctrica/electrónica es que la placa no esté recibiendo una señal correcta desde el sensor/electrodo de ionización. También pueden influir conectores flojos, cableado, mala lectura del sensor o falla del módulo/placa.';
  if(p.includes('chispa')) return 'Si hace chispa pero no prende, la parte eléctrica a revisar visualmente es el electrodo de encendido, el cable de alta, el módulo/chispero, conectores y la placa. También conviene confirmar si la chispa aparece en el lugar correcto.';
  if(p.includes('no enciende') || p.includes('no prende')) return 'Si no enciende, primero se relaciona con alimentación eléctrica: pilas/fuente, conectores, sensor de caudal/micro switch, módulo de encendido o placa electrónica.';
  if(p.includes('placa')) return 'La placa electrónica coordina el encendido, recibe señales de sensores y decide si habilita o corta el funcionamiento. Un problema de placa puede verse como falta de chispa, corte rápido, código de error o comportamiento intermitente.';
  if(p.includes('sensor') || p.includes('ionizacion')) return 'El sensor/electrodo de ionización confirma la señal de funcionamiento al circuito electrónico. Si la señal no llega bien, el equipo puede cortar aunque haya intentado encender.';
  if(r) return iaLimpiarTextoCurso(r.texto);
  return 'La consulta está relacionada con calefones ionizados. La AI revisa primero el curso y luego intenta ampliar con información externa para dar una explicación más completa.';
}

function iaHerramientasHTMLV7(pregunta){
  const herramientas = iaHerramientasSugeridas(pregunta);
  return `<p><b>Herramientas útiles para una revisión visual/electrónica básica:</b><br>${herramientas.map(iaEscape).join(', ')}.</p>`;
}

function iaRespuestaCursoV7(pregunta){
  const diag = iaDiagnosticoElectrico(pregunta);
  const resultados = iaBuscarCursoV7(pregunta, 6);
  const r = resultados[0];
  let html = '';

  html += `<p><b>Consulta:</b> ${iaEscape(pregunta)}</p>`;
  if(diag){
    html += `<p><b>Problema detectado:</b> ${iaEscape(diag.nombre)}</p>`;
  }else if(iaPreguntaEsConceptualV7(pregunta)){
    html += `<p><b>Tema detectado:</b> explicación del calefón ionizado.</p>`;
  }else{
    html += `<p><b>Tema detectado:</b> diagnóstico sobre calefón ionizado.</p>`;
  }

  if(r){
    html += `<p><b>Coincidencia en tu curso:</b><br>${iaEscape(r.clase)} — segundo aproximado ${iaEscape(r.segundo)}</p>`;
    html += iaImagenHTML(r);
    html += `<p><b>Explicación basada en el curso:</b><br>${iaEscape(iaExplicacionLocalV7(pregunta, diag, resultados))}</p>`;
    html += `<p><b>Texto relacionado del curso:</b><br>${iaEscape(iaLimpiarTextoCurso(r.texto))}</p>`;
    html += iaFuentePDFHTML(r);
    if(resultados.length > 1){
      html += `<details><summary>Ver más partes relacionadas del curso</summary>`;
      resultados.slice(1).forEach(x=>{
        html += `<div class="ia-extra"><b>${iaEscape(x.clase)}</b> — segundo ${iaEscape(x.segundo)}${iaImagenHTML(x)}<br>${iaEscape(iaLimpiarTextoCurso(x.texto))}${iaFuentePDFHTML(x)}</div>`;
      });
      html += `</details>`;
    }
  }else{
    html += `<p><b>En el curso:</b> no encontré una coincidencia exacta, pero puedo explicar el problema desde la base general de calefones ionizados y complementar con Gemini.</p>`;
    html += `<p><b>Explicación inicial:</b><br>${iaEscape(iaExplicacionLocalV7(pregunta, diag, resultados))}</p>`;
  }

  html += iaHerramientasHTMLV7(pregunta);
  return {html, resultados, contextoCurso: iaTextoCursoParaGeminiV7(resultados), tieneImagenCurso: !!(resultados && resultados.some(x=>x.imagen))};
}

async function iaConsultarGemini(pregunta, contextoCurso=''){
  const contexto = iaContextoConversacion();
  const prompt = `Sos AI Aspe, un asistente para alumnos/clientes del curso de calefones ionizados.

Objetivo: responder SIEMPRE con una explicación clara, útil y ordenada, combinando lo encontrado en el curso con conocimiento general sobre calefones ionizados.

Reglas:
- Respondé solo sobre calefones ionizados y su diagnóstico eléctrico/electrónico.
- Podés hablar de electrodo de encendido, sensor/electrodo de ionización, chispero, módulo de encendido, placa electrónica, pilas/fuente, cableado, conectores, pantalla/códigos, sensores, caudal eléctrico y temperatura.
- No des instrucciones de plomería ni de intervención de gas. Si algo excede lo eléctrico/electrónico, aclaralo sin extenderte.
- No menciones que buscaste en Google. Decí "Explicación ampliada".
- Usá lenguaje simple para cliente/alumno.
- Incluí herramientas útiles solo para revisión visual/electrónica básica.
- Terminá con preguntas para seguir la conversación.

Conversación anterior:
${contexto || 'Sin conversación anterior.'}

Información encontrada en el curso/PDF/SRT:
${contextoCurso || 'No hubo coincidencia exacta en el curso.'}

Pregunta actual:
${pregunta}

Respondé con este formato:
1) Qué puede estar pasando.
2) Explicación simple.
3) Qué mirar de forma visual en la parte eléctrica/electrónica.
4) Herramientas útiles.
5) Relación con el curso.
6) Preguntas para seguir.`;

  for(const modelo of IA_ASPE_V7_MODELOS){
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent?key=${IA_ASPE_GEMINI_API_KEY}`;
    const payloads = [
      {contents:[{parts:[{text:prompt}]}], tools:[{google_search:{}}]},
      {contents:[{parts:[{text:prompt}]}]}
    ];
    for(const body of payloads){
      try{
        const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)});
        if(!res.ok) continue;
        const data = await res.json();
        const txt = data?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || '';
        if(txt.trim()) return txt.trim();
      }catch(e){
        // no mostramos errores al cliente
      }
    }
  }
  return '';
}

function iaGeminiFallbackV7(pregunta, curso){
  const diag = iaDiagnosticoElectrico(pregunta);
  const resultados = curso?.resultados || [];
  const base = iaExplicacionLocalV7(pregunta, diag, resultados);
  const relacion = resultados[0] ? `En tu curso se relaciona principalmente con ${resultados[0].clase}, segundo aproximado ${resultados[0].segundo}.` : 'No encontré una clase exacta, pero la consulta sigue dentro del tema de calefones ionizados.';
  return `Qué puede estar pasando: ${base}\n\nExplicación ampliada: el diagnóstico conviene pensarlo por señales eléctricas: alimentación, orden de encendido, chispa, confirmación por ionización y respuesta de la placa. Cuando una de esas señales falla, el equipo puede no encender, cortar rápido, marcar código o quedar intermitente.\n\nQué mirar de forma visual: estado de pilas/fuente, conectores flojos, cables cortados o sulfatados, electrodo/sensor visible, humedad cerca de la placa y código que aparezca en pantalla.\n\nRelación con el curso: ${relacion}\n\nPara seguir: ¿hace chispa?, ¿enciende unos segundos y corta?, ¿marca algún código?, ¿usa pilas o fuente?`;
}

async function iaResponderCompleto(pregunta){
  if(!iaEsConsultaCalefonV7(pregunta)){
    return `<p><b>Esta AI solo responde sobre calefones ionizados.</b></p><p>Podés preguntarme por encendido, chispa, electrodo, ionización, placa electrónica, pilas/fuente, sensores, cableado, conectores, pantalla/códigos o fallas de corte.</p>`;
  }

  const curso = iaRespuestaCursoV7(pregunta);
  let html = curso.html;

  const respuestaGemini = await iaConsultarGemini(pregunta, curso.contextoCurso);
  const ampliada = respuestaGemini || iaGeminiFallbackV7(pregunta, curso);
  html += `<div class="ia-gemini-box"><b>Explicación ampliada:</b><br>${iaEscape(ampliada).replace(/\n/g,'<br>')}</div>`;

  if(!curso.tieneImagenCurso){
    html += iaCrearLinkImagenesExterno(pregunta);
  }

  html += `<div class="ia-warning ia-warning-small"><b>Alcance:</b> explicación educativa sobre calefones ionizados, enfocada en parte eléctrica/electrónica y contenido del curso.</div>`;
  return html;
}

async function iaEnviar(){
  const input=document.getElementById('iaPregunta');
  const pregunta=input.value.trim();
  if(!pregunta) return;
  IA_ASPE_CHAT_HISTORY.push({rol:'Alumno', texto:pregunta});
  iaAgregar(`<b>Alumno:</b> ${iaEscape(pregunta)}`, 'user');
  input.value = '';
  iaAgregar(`<b>AI Aspe:</b><br>Analizando el curso y preparando una explicación completa...`, 'bot');
  const html = await iaResponderCompleto(pregunta);
  IA_ASPE_CHAT_HISTORY.push({rol:'AI Aspe', texto:html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,1200)});
  iaAgregar(`<b>AI Aspe:</b><br>${html}`, 'bot');
}

