let IA_ASPE_MIC_PERMISSION_OK = sessionStorage.getItem('ia_aspe_mic_permiso_sesion') === '1';
let IA_ASPE_RECOGNITION = null;
let IA_ASPE_RECOGNIZING = false;
let IA_ASPE_FINAL_TEXT = '';

function iaActualizarBotonMicrofono(escuchando){
  const btn = document.getElementById('iaMicBtn');
  if(!btn) return;
  if(escuchando){
    btn.classList.add('ia-listening');
    btn.innerHTML = `<span>🎙️</span><span class="ia-mic-dot"></span>`;
    btn.title = 'Tocar para dejar de hablar';
  }else{
    btn.classList.remove('ia-listening');
    btn.innerHTML = `<span>🎙️</span>`;
    btn.title = 'Tocar para hablar';
  }
}

async function iaPedirPermisoMicrofonoUnaVez(){
  if(IA_ASPE_MIC_PERMISSION_OK) return true;
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return false;
  try{
    const stream = await navigator.mediaDevices.getUserMedia({audio:true});
    stream.getTracks().forEach(t=>t.stop());
    IA_ASPE_MIC_PERMISSION_OK = true;
    sessionStorage.setItem('ia_aspe_mic_permiso_sesion','1');
    return true;
  }catch(e){
    return false;
  }
}

async function iaMicrofono(){
  const estado = document.getElementById('iaMicEstado');
  const input = document.getElementById('iaPregunta');
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;

  if(!SR){
    if(estado) estado.innerText = 'Tu navegador no soporta reconocimiento de voz. Probá con Chrome.';
    return;
  }

  // Si ya esta escuchando, el mismo boton corta la escucha.
  if(IA_ASPE_RECOGNIZING && IA_ASPE_RECOGNITION){
    try{ IA_ASPE_RECOGNITION.stop(); }catch(e){}
    IA_ASPE_RECOGNIZING = false;
    iaActualizarBotonMicrofono(false);
    if(estado) estado.innerText = 'Escucha detenida. Podés editar el texto y tocar Enviar.';
    return;
  }

  const ok = await iaPedirPermisoMicrofonoUnaVez();
  if(!ok){
    if(estado) estado.innerText = 'No se pudo activar el micrófono. Permití el micrófono en el navegador.';
    iaActualizarBotonMicrofono(false);
    return;
  }

  IA_ASPE_RECOGNITION = new SR();
  IA_ASPE_RECOGNITION.lang = 'es-AR';
  IA_ASPE_RECOGNITION.interimResults = true;
  IA_ASPE_RECOGNITION.continuous = true;
  IA_ASPE_FINAL_TEXT = input ? input.value.trim() : '';
  if(IA_ASPE_FINAL_TEXT) IA_ASPE_FINAL_TEXT += ' ';

  IA_ASPE_RECOGNITION.onstart = () => {
    IA_ASPE_RECOGNIZING = true;
    iaActualizarBotonMicrofono(true);
    if(estado) estado.innerText = 'Escuchando... tocá de nuevo el micrófono para dejar de hablar.';
  };

  IA_ASPE_RECOGNITION.onresult = (ev) => {
    let temp = '';
    for(let i = ev.resultIndex; i < ev.results.length; i++){
      const texto = ev.results[i][0].transcript;
      if(ev.results[i].isFinal){
        IA_ASPE_FINAL_TEXT += texto + ' ';
      }else{
        temp += texto;
      }
    }
    if(input) input.value = (IA_ASPE_FINAL_TEXT + temp).replace(/\s+/g,' ').trim();
  };

  IA_ASPE_RECOGNITION.onerror = (ev) => {
    IA_ASPE_RECOGNIZING = false;
    iaActualizarBotonMicrofono(false);
    if(estado){
      if(ev && ev.error === 'not-allowed'){
        estado.innerText = 'Permiso rechazado. Tocá el candado de la barra de dirección y permití el micrófono.';
      }else{
        estado.innerText = 'No pude escuchar bien. Tocá el micrófono y probá de nuevo.';
      }
    }
  };

  IA_ASPE_RECOGNITION.onend = () => {
    IA_ASPE_RECOGNIZING = false;
    iaActualizarBotonMicrofono(false);
    if(estado) estado.innerText = 'Texto detectado. Podés editarlo y después tocar Enviar.';
  };

  try{
    IA_ASPE_RECOGNITION.start();
  }catch(e){
    IA_ASPE_RECOGNIZING = false;
    iaActualizarBotonMicrofono(false);
    if(estado) estado.innerText = 'El micrófono ya estaba activo o el navegador no lo inició. Probá tocar de nuevo.';
  }
}

