/* =========================
   AI ASPE V9 - MICROFONO CORREGIDO
   - Botón normal: muestra micrófono.
   - Escuchando: muestra SOLO un círculo blanco.
   - Primer uso pide permiso; después en la misma sesión no vuelve a pedir desde el código.
   - Para cortar: tocar el mismo botón.
   - El texto detectado queda escrito en el textarea y NO se envía solo.
========================= */
let IA_ASPE_V9_RECOGNITION = null;
let IA_ASPE_V9_LISTENING = false;
let IA_ASPE_V9_SHOULD_LISTEN = false;
let IA_ASPE_V9_FINAL = '';
let IA_ASPE_V9_MIC_SESSION_OK = sessionStorage.getItem('ia_aspe_microfono_ok_v9') === '1';

(function(){
  const style = document.createElement('style');
  style.textContent = `
    .ia-mic{position:relative;display:flex!important;align-items:center;justify-content:center;min-height:54px;overflow:hidden;}
    .ia-mic .ia-mic-dot{width:17px;height:17px;border-radius:50%;background:#fff;display:inline-block;box-shadow:0 0 0 5px rgba(255,255,255,.18);}
    .ia-mic.ia-listening{background:#dc2626!important;animation:iaMicV9Pulse 1.05s infinite;}
    .ia-mic.ia-listening .ia-mic-icon{display:none!important;}
    @keyframes iaMicV9Pulse{0%{box-shadow:0 0 0 0 rgba(220,38,38,.35)}70%{box-shadow:0 0 0 14px rgba(220,38,38,0)}100%{box-shadow:0 0 0 0 rgba(220,38,38,0)}}
  `;
  document.head.appendChild(style);
})();

function iaActualizarBotonMicrofono(escuchando){
  const btn = document.getElementById('iaMicBtn') || document.querySelector('.ia-mic');
  if(!btn) return;
  if(escuchando){
    btn.classList.add('ia-listening');
    btn.innerHTML = `<span class="ia-mic-dot" aria-hidden="true"></span>`;
    btn.title = 'Escuchando. Tocá para dejar de hablar';
  }else{
    btn.classList.remove('ia-listening');
    btn.innerHTML = `<span class="ia-mic-icon">🎙️</span>`;
    btn.title = 'Tocar para hablar';
  }
}

async function iaPermisoMicrofonoV9(){
  if(IA_ASPE_V9_MIC_SESSION_OK) return true;

  // Si Chrome ya tiene permiso concedido, no pedimos de nuevo.
  try{
    if(navigator.permissions && navigator.permissions.query){
      const perm = await navigator.permissions.query({name:'microphone'});
      if(perm && perm.state === 'granted'){
        IA_ASPE_V9_MIC_SESSION_OK = true;
        sessionStorage.setItem('ia_aspe_microfono_ok_v9','1');
        return true;
      }
    }
  }catch(e){}

  // Primera vez: esto dispara el cartel del navegador. Elegir "Permitir mientras visito el sitio".
  try{
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return true;
    const stream = await navigator.mediaDevices.getUserMedia({audio:true});
    stream.getTracks().forEach(track => track.stop());
    IA_ASPE_V9_MIC_SESSION_OK = true;
    sessionStorage.setItem('ia_aspe_microfono_ok_v9','1');
    return true;
  }catch(e){
    return false;
  }
}

function iaCrearReconocimientoV9(){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR) return null;

  const rec = new SR();
  rec.lang = 'es-AR';
  rec.continuous = true;
  rec.interimResults = true;
  rec.maxAlternatives = 1;

  rec.onstart = function(){
    IA_ASPE_V9_LISTENING = true;
    iaActualizarBotonMicrofono(true);
    const estado = document.getElementById('iaMicEstado');
    if(estado) estado.innerText = 'Escuchando... hablá ahora. Tocá de nuevo el micrófono para cortar.';
  };

  rec.onresult = function(ev){
    const input = document.getElementById('iaPregunta');
    let temporal = '';

    for(let i = ev.resultIndex; i < ev.results.length; i++){
      const parte = ev.results[i][0].transcript || '';
      if(ev.results[i].isFinal){
        IA_ASPE_V9_FINAL += parte + ' ';
      }else{
        temporal += parte + ' ';
      }
    }

    if(input){
      input.value = (IA_ASPE_V9_FINAL + temporal).replace(/\s+/g,' ').trim();
      input.focus();
    }
  };

  rec.onerror = function(ev){
    const estado = document.getElementById('iaMicEstado');
    if(!estado) return;

    if(ev && ev.error === 'not-allowed'){
      estado.innerText = 'El permiso fue rechazado. Tocá el candado de la barra de dirección y permití el micrófono.';
      IA_ASPE_V9_SHOULD_LISTEN = false;
    }else if(ev && ev.error === 'no-speech'){
      estado.innerText = 'No detecté palabras. Tocá el micrófono y hablá cerca del dispositivo.';
    }else if(ev && ev.error === 'audio-capture'){
      estado.innerText = 'No encontré micrófono activo. Revisá el micrófono de Windows/Chrome.';
      IA_ASPE_V9_SHOULD_LISTEN = false;
    }else{
      estado.innerText = 'No pude escuchar bien. Probá de nuevo hablando más claro.';
    }
  };

  rec.onend = function(){
    IA_ASPE_V9_LISTENING = false;
    iaActualizarBotonMicrofono(false);

    // Chrome a veces corta solo. Si el usuario no tocó para cortar, reiniciamos para seguir escuchando.
    if(IA_ASPE_V9_SHOULD_LISTEN){
      setTimeout(function(){
        try{
          IA_ASPE_V9_RECOGNITION = iaCrearReconocimientoV9();
          IA_ASPE_V9_RECOGNITION.start();
        }catch(e){
          IA_ASPE_V9_SHOULD_LISTEN = false;
          const estado = document.getElementById('iaMicEstado');
          if(estado) estado.innerText = 'Escucha detenida. Podés editar el texto y tocar Enviar.';
        }
      }, 250);
      return;
    }

    const estado = document.getElementById('iaMicEstado');
    if(estado) estado.innerText = 'Escucha detenida. Podés editar el texto y tocar Enviar.';
  };

  return rec;
}

async function iaMicrofono(){
  const estado = document.getElementById('iaMicEstado');
  const input = document.getElementById('iaPregunta');
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;

  if(!SR){
    if(estado) estado.innerText = 'Tu navegador no soporta reconocimiento de voz. Usá Google Chrome.';
    return;
  }

  // Si está escuchando, el mismo botón corta.
  if(IA_ASPE_V9_LISTENING || IA_ASPE_V9_SHOULD_LISTEN){
    IA_ASPE_V9_SHOULD_LISTEN = false;
    try{ if(IA_ASPE_V9_RECOGNITION) IA_ASPE_V9_RECOGNITION.stop(); }catch(e){}
    IA_ASPE_V9_LISTENING = false;
    iaActualizarBotonMicrofono(false);
    if(estado) estado.innerText = 'Escucha detenida. Podés editar el texto y tocar Enviar.';
    return;
  }

  const permiso = await iaPermisoMicrofonoV9();
  if(!permiso){
    if(estado) estado.innerText = 'No se pudo activar el micrófono. Permití el micrófono en Chrome.';
    iaActualizarBotonMicrofono(false);
    return;
  }

  IA_ASPE_V9_FINAL = input ? input.value.trim() : '';
  if(IA_ASPE_V9_FINAL) IA_ASPE_V9_FINAL += ' ';
  IA_ASPE_V9_SHOULD_LISTEN = true;
  IA_ASPE_V9_RECOGNITION = iaCrearReconocimientoV9();

  try{
    IA_ASPE_V9_RECOGNITION.start();
  }catch(e){
    IA_ASPE_V9_SHOULD_LISTEN = false;
    IA_ASPE_V9_LISTENING = false;
    iaActualizarBotonMicrofono(false);
    if(estado) estado.innerText = 'No pude iniciar el micrófono. Esperá un segundo y tocá de nuevo.';
  }
}

