/* =========================
   AI ASPE V10 - Gemini con pregunta exacta + contexto electrico/electronico
   - Si el alumno pregunta una definicion, NO lo marca como problema.
   - Gemini recibe la misma pregunta + "Sobre calefones ionizados parte electrica/electronica".
   - La respuesta final combina curso + explicacion ampliada.
========================= */

function iaEsPreguntaDefinicionV10(pregunta){
  const p = iaNormalizar(pregunta || '');
  return (
    p.includes('que es') || p.includes('qué es') ||
    p.includes('que significa') || p.includes('qué significa') ||
    p.includes('explicame que es') || p.includes('explicame qué es') ||
    p.includes('definicion') || p.includes('definición') ||
    p.includes('para que sirve') || p.includes('para qué sirve') ||
    p.includes('como funciona') || p.includes('cómo funciona') ||
    p.includes('diferencia entre')
  );
}

function iaDiagnosticoElectricoV10(pregunta){
  const p = iaNormalizar(pregunta || '');

  // Si el usuario pide una definicion, no lo tratamos como falla.
  if(iaEsPreguntaDefinicionV10(pregunta)) return null;

  return iaDiagnosticoElectrico(pregunta);
}

function iaTemaDetectadoTextoV10(pregunta){
  const p = iaNormalizar(pregunta || '');
  if(iaEsPreguntaDefinicionV10(pregunta)){
    if(p.includes('placa')) return 'definición de placa electrónica';
    if(p.includes('ionizacion') || p.includes('ionización') || p.includes('ionizado')) return 'explicación de ionización / calefón ionizado';
    if(p.includes('electrodo')) return 'definición de electrodo';
    if(p.includes('sensor')) return 'definición de sensor';
    if(p.includes('chispa') || p.includes('chispero')) return 'explicación del sistema de chispa/encendido';
    return 'explicación del curso';
  }
  const diag = iaDiagnosticoElectrico(pregunta);
  return diag ? diag.nombre : 'diagnóstico eléctrico/electrónico';
}

function iaBusquedaGeminiV10(pregunta){
  let limpia = String(pregunta || '').trim();
  limpia = limpia.replace(/\s+/g,' ');
  return `${limpia} Sobre calefones ionizados parte eléctrica/electrónica`;
}

function iaExplicacionLocalV10(pregunta, diag, resultados){
  const p = iaNormalizar(pregunta || '');
  const r = resultados && resultados[0];

  if(iaEsPreguntaDefinicionV10(pregunta)){
    if(p.includes('placa')){
      return 'La placa electrónica es el circuito que coordina el funcionamiento eléctrico del calefón ionizado. Recibe señales de sensores, controla el encendido, interpreta la señal de ionización, puede mostrar códigos en display y decide si el equipo continúa funcionando o corta por falta de señal correcta.';
    }
    if(p.includes('ionizado') || p.includes('ionizacion') || p.includes('ionización')){
      return 'Un calefón ionizado usa un sistema electrónico de encendido y control. En vez de depender de un piloto permanente, utiliza electrodos, sensores, módulo/placa y señal de ionización para confirmar que el encendido fue correcto y mantener el funcionamiento controlado.';
    }
    if(p.includes('electrodo')){
      return 'El electrodo es una pieza eléctrica que puede participar en la chispa de encendido o en la detección por ionización. Según el modelo, puede haber electrodo de encendido y electrodo/sensor de ionización.';
    }
    if(p.includes('sensor')){
      return 'Un sensor en un calefón ionizado es un componente que informa a la placa sobre una condición del equipo: presencia de señal de ionización, temperatura, caudal o estado de seguridad eléctrica/electrónica.';
    }
    if(r) return iaLimpiarTextoCurso(r.texto);
  }

  return iaExplicacionLocalV7(pregunta, diag, resultados);
}

function iaRespuestaCursoV7(pregunta){
  const diag = iaDiagnosticoElectricoV10(pregunta);
  const resultados = iaBuscarCursoV7(pregunta, 6);
  const r = resultados[0];
  let html = '';

  html += `<p><b>Consulta:</b> ${iaEscape(pregunta)}</p>`;
  html += `<p><b>Tema detectado:</b> ${iaEscape(iaTemaDetectadoTextoV10(pregunta))}</p>`;

  if(r){
    html += `<p><b>Coincidencia en tu curso:</b><br>${iaEscape(r.clase)} — segundo aproximado ${iaEscape(r.segundo)}</p>`;
    html += iaImagenHTML(r);
    html += `<p><b>Explicación basada en el curso:</b><br>${iaEscape(iaExplicacionLocalV10(pregunta, diag, resultados))}</p>`;
    html += `<p><b>Texto relacionado del curso:</b><br>${iaEscape(iaLimpiarTextoCurso(r.texto))}</p>`;
    html += iaFuentePDFHTML(r);
    if(resultados.length > 1){
      html += `<details><summary>Ver más partes relacionadas del curso</summary>`;
      resultados.slice(1).forEach(x=>{
        html += `<div class="ia-extra"><b>${iaEscape(x.clase)}</b> — segundo ${iaEscape(x.segundo)}${iaImagenHTML(x)}<br>${iaEscape(iaLimpiarTextoCurso(x.texto))}${iaFuentePDFHTML(x)}</div>`;
      });
      html += `</details>`;
    }
  }else{
    html += `<p><b>En el curso:</b> no encontré una coincidencia exacta, pero la consulta sigue dentro de calefones ionizados y se amplía con Gemini.</p>`;
    html += `<p><b>Explicación inicial:</b><br>${iaEscape(iaExplicacionLocalV10(pregunta, diag, resultados))}</p>`;
  }

  html += iaHerramientasHTMLV7(pregunta);
  return {html, resultados, contextoCurso: iaTextoCursoParaGeminiV7(resultados), tieneImagenCurso: !!(resultados && resultados.some(x=>x.imagen))};
}

async function iaConsultarGemini(pregunta, contextoCurso=''){
  const contexto = iaContextoConversacion();
  const preguntaWeb = iaBusquedaGeminiV10(pregunta);

  const prompt = `Sos AI Aspe, asistente del Curso Aspe sobre calefones ionizados.

Tu tarea es ampliar la respuesta combinando:
1) lo encontrado en el curso del usuario,
2) conocimiento general y, cuando esté disponible, búsqueda web mediante la herramienta de Gemini.

Pregunta original del alumno:
${pregunta}

Pregunta que debes usar como enfoque de búsqueda/contexto externo:
${preguntaWeb}

Reglas obligatorias:
- Respondé solo sobre calefones ionizados, parte eléctrica/electrónica.
- No expliques plomería, cañerías, instalación de gas ni trabajos de gas.
- Si la pregunta es una definición, explicala como definición, no como falla.
- Si la pregunta es una falla, explicá posibles causas eléctricas/electrónicas.
- No digas "busqué en Google" ni muestres errores técnicos.
- Usá lenguaje claro para cliente/alumno.
- Sumá herramientas útiles solamente para revisión visual/electrónica básica.
- Terminá con 2 o 3 preguntas para seguir la conversación.

Conversación anterior:
${contexto || 'Sin conversación anterior.'}

Información encontrada en el curso/PDF/SRT:
${contextoCurso || 'No hubo coincidencia exacta en el curso.'}

Formato de respuesta:
1) Definición o qué puede estar pasando.
2) Explicación simple.
3) Relación con la parte eléctrica/electrónica del calefón ionizado.
4) Qué mirar de forma visual, sin desarmar partes peligrosas.
5) Herramientas útiles.
6) Preguntas para seguir.`;

  for(const modelo of IA_ASPE_V7_MODELOS){
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent?key=${IA_ASPE_GEMINI_API_KEY}`;
    const payloads = [
      {contents:[{parts:[{text:prompt}]}], tools:[{google_search:{}}]},
      {contents:[{parts:[{text:prompt}]}]}
    ];
    for(const body of payloads){
      try{
        const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)});
        if(!res.ok) continue;
        const data = await res.json();
        const txt = data?.candidates?.[0]?.content?.parts?.map(p=>p.text).join('\n') || '';
        if(txt.trim()) return txt.trim();
      }catch(e){
        // No se muestra error al cliente. Usa respuesta local.
      }
    }
  }
  return '';
}

function iaGeminiFallbackV7(pregunta, curso){
  const diag = iaDiagnosticoElectricoV10(pregunta);
  const resultados = curso?.resultados || [];
  const base = iaExplicacionLocalV10(pregunta, diag, resultados);
  const relacion = resultados[0] ? `En tu curso se relaciona principalmente con ${resultados[0].clase}, segundo aproximado ${resultados[0].segundo}.` : 'No encontré una clase exacta, pero la consulta sigue dentro del tema de calefones ionizados.';

  if(iaEsPreguntaDefinicionV10(pregunta)){
    return `${base}\n\nExplicación ampliada: dentro de un calefón ionizado, este tema se entiende siempre como parte de una cadena eléctrica/electrónica: alimentación, placa o módulo, sensores, señal de encendido, señal de ionización, conectores y respuesta del equipo.\n\nRelación con el curso: ${relacion}\n\nHerramientas útiles: linterna, multímetro solo para mediciones seguras si la persona sabe usarlo, limpieza visual externa y revisión de conectores visibles.\n\nPara seguir: ¿querés que lo explique más fácil?, ¿querés que lo relacione con una falla concreta?, ¿tu calefón usa pilas, fuente o display?`;
  }

  return `Qué puede estar pasando: ${base}\n\nExplicación ampliada: el diagnóstico conviene pensarlo por señales eléctricas: alimentación, orden de encendido, chispa, confirmación por ionización y respuesta de la placa. Cuando una de esas señales falla, el equipo puede no encender, cortar rápido, marcar código o quedar intermitente.\n\nQué mirar de forma visual: estado de pilas/fuente, conectores flojos, cables cortados o sulfatados, electrodo/sensor visible, humedad cerca de la placa y código que aparezca en pantalla.\n\nRelación con el curso: ${relacion}\n\nPara seguir: ¿hace chispa?, ¿enciende unos segundos y corta?, ¿marca algún código?, ¿usa pilas o fuente?`;
}

function iaCrearLinkImagenesExterno(pregunta){
  const consulta = iaBusquedaGeminiV10(iaLimpiarPreguntaParaImagenesV7(pregunta));
  const q = encodeURIComponent(consulta);
  return `<div class="ia-google-box"><b>¿Este es el problema o componente que tenés?</b><br><a class="ia-img-link" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${q}">Apretá aquí</a><br><small>Se abre una búsqueda de imágenes solo como referencia visual cuando no hay imagen clara en el curso.</small></div>`;
}

/* Ajuste visual del boton de microfono: escuchando = solo circulo blanco */
function iaActualizarBotonMicrofono(escuchando){
  const btn = document.getElementById('iaMicBtn');
  if(!btn) return;
  if(escuchando){
    btn.classList.add('ia-listening');
    btn.innerHTML = `<span class="ia-mic-dot"></span>`;
    btn.title = 'Tocar para dejar de hablar';
  }else{
    btn.classList.remove('ia-listening');
    btn.innerHTML = `<span>🎙️</span>`;
    btn.title = 'Tocar para hablar';
  }
}

/* =========================================================
   V11 MICROFONO - PERMISO UNA VEZ POR SESION
   IMPORTANTE: no se puede ocultar el cartel nativo de Chrome.
   Esta version evita llamar getUserMedia en cada toque.
   Primer toque: Chrome pide permiso. Despues el boton solo prende/corta.
========================================================= */
(function(){
  window.IA_ASPE_V11_MIC_STARTED = false;
  window.IA_ASPE_V11_RECOGNITION = null;
  window.IA_ASPE_V11_LISTENING = false;
  window.IA_ASPE_V11_WANT_LISTEN = false;
  window.IA_ASPE_V11_FINAL = '';
  window.IA_ASPE_V11_SESSION_KEY = 'ia_aspe_microfono_permiso_solo_esta_pestana_v11';

  function estadoMic(txt){
    const e = document.getElementById('iaMicEstado');
    if(e) e.innerText = txt;
  }

  window.iaActualizarBotonMicrofono = function(escuchando){
    const btn = document.getElementById('iaMicBtn') || document.querySelector('.ia-mic');
    if(!btn) return;
    if(escuchando){
      btn.classList.add('ia-listening');
      btn.innerHTML = '<span class="ia-mic-dot" aria-hidden="true"></span>';
      btn.title = 'Tocar para dejar de hablar';
      btn.setAttribute('aria-label','Dejar de hablar');
    }else{
      btn.classList.remove('ia-listening');
      btn.innerHTML = '<span class="ia-mic-icon">🎙️</span>';
      btn.title = 'Tocar para hablar';
      btn.setAttribute('aria-label','Tocar para hablar');
    }
  };

  window.iaPermisoMicrofonoV11 = async function(){
    /*
      No usamos getUserMedia en cada toque porque eso puede abrir el cartel de Chrome otra vez.
      La primera vez se solicita permiso al iniciar SpeechRecognition.start().
      sessionStorage dura mientras la pestaña/sesion siga abierta.
    */
    try{
      if(sessionStorage.getItem(window.IA_ASPE_V11_SESSION_KEY) === '1') return true;
      if(navigator.permissions && navigator.permissions.query){
        try{
          const perm = await navigator.permissions.query({name:'microphone'});
          if(perm && perm.state === 'granted'){
            sessionStorage.setItem(window.IA_ASPE_V11_SESSION_KEY,'1');
            return true;
          }
        }catch(e){}
      }
    }catch(e){}
    return true;
  };

  window.iaCrearReconocimientoV11 = function(){
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if(!SR) return null;

    const rec = new SR();
    rec.lang = 'es-AR';
    rec.continuous = true;
    rec.interimResults = true;
    rec.maxAlternatives = 1;

    rec.onstart = function(){
      window.IA_ASPE_V11_LISTENING = true;
      sessionStorage.setItem(window.IA_ASPE_V11_SESSION_KEY,'1');
      iaActualizarBotonMicrofono(true);
      estadoMic('Escuchando... tocá de nuevo el micrófono para cortar. No se envía solo.');
    };

    rec.onresult = function(ev){
      const input = document.getElementById('iaPregunta');
      let temporal = '';
      for(let i = ev.resultIndex; i < ev.results.length; i++){
        const texto = (ev.results[i][0] && ev.results[i][0].transcript ? ev.results[i][0].transcript : '').trim();
        if(!texto) continue;
        if(ev.results[i].isFinal){
          window.IA_ASPE_V11_FINAL += texto + ' ';
        }else{
          temporal += texto + ' ';
        }
      }
      if(input){
        input.value = (window.IA_ASPE_V11_FINAL + temporal).replace(/\s+/g,' ').trim();
        input.focus();
      }
    };

    rec.onerror = function(ev){
      const error = ev && ev.error ? ev.error : '';
      if(error === 'not-allowed' || error === 'service-not-allowed'){
        window.IA_ASPE_V11_WANT_LISTEN = false;
        sessionStorage.removeItem(window.IA_ASPE_V11_SESSION_KEY);
        estadoMic('Permiso rechazado. Tocá el candado de Chrome y permití el micrófono.');
      }else if(error === 'no-speech'){
        estadoMic('No detecté palabras. Hablá cerca del micrófono o tocá de nuevo para cortar.');
      }else if(error === 'audio-capture'){
        window.IA_ASPE_V11_WANT_LISTEN = false;
        estadoMic('No encontré micrófono activo. Revisá el micrófono de Windows/Chrome.');
      }else{
        estadoMic('No pude escuchar bien. Probá de nuevo hablando más claro.');
      }
    };

    rec.onend = function(){
      window.IA_ASPE_V11_LISTENING = false;
      iaActualizarBotonMicrofono(false);

      if(window.IA_ASPE_V11_WANT_LISTEN){
        /* Chrome puede cortar solo. Reintentamos sin pedir getUserMedia de nuevo. */
        setTimeout(function(){
          try{
            window.IA_ASPE_V11_RECOGNITION = iaCrearReconocimientoV11();
            if(window.IA_ASPE_V11_RECOGNITION) window.IA_ASPE_V11_RECOGNITION.start();
          }catch(e){
            window.IA_ASPE_V11_WANT_LISTEN = false;
            iaActualizarBotonMicrofono(false);
            estadoMic('Escucha detenida. Podés editar el texto y tocar Enviar.');
          }
        }, 300);
        return;
      }

      estadoMic('Escucha detenida. Podés editar el texto y tocar Enviar.');
    };

    return rec;
  };

  window.iaMicrofono = async function(){
    const input = document.getElementById('iaPregunta');
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;

    if(!SR){
      estadoMic('Tu navegador no soporta reconocimiento de voz. Usá Google Chrome.');
      return;
    }

    if(window.IA_ASPE_V11_LISTENING || window.IA_ASPE_V11_WANT_LISTEN){
      window.IA_ASPE_V11_WANT_LISTEN = false;
      try{ if(window.IA_ASPE_V11_RECOGNITION) window.IA_ASPE_V11_RECOGNITION.stop(); }catch(e){}
      window.IA_ASPE_V11_LISTENING = false;
      iaActualizarBotonMicrofono(false);
      estadoMic('Escucha detenida. Podés editar el texto y tocar Enviar.');
      return;
    }

    const permisoOk = await iaPermisoMicrofonoV11();
    if(!permisoOk){
      iaActualizarBotonMicrofono(false);
      estadoMic('No se pudo activar el micrófono. Permití el micrófono en Chrome.');
      return;
    }

    window.IA_ASPE_V11_FINAL = input ? input.value.trim() : '';
    if(window.IA_ASPE_V11_FINAL) window.IA_ASPE_V11_FINAL += ' ';
    window.IA_ASPE_V11_WANT_LISTEN = true;
    window.IA_ASPE_V11_RECOGNITION = iaCrearReconocimientoV11();

    try{
      if(window.IA_ASPE_V11_RECOGNITION) window.IA_ASPE_V11_RECOGNITION.start();
    }catch(e){
      window.IA_ASPE_V11_WANT_LISTEN = false;
      window.IA_ASPE_V11_LISTENING = false;
      iaActualizarBotonMicrofono(false);
      estadoMic('No pude iniciar el micrófono. Esperá un segundo y tocá de nuevo.');
    }
  };

  /* Sobrescribo la vista para dejar el texto claro y el boton con id correcto. */
  const oldMostrarAIAspe = window.mostrarAIAspe;
  window.mostrarAIAspe = function(){
    if(typeof oldMostrarAIAspe === 'function') oldMostrarAIAspe();
    setTimeout(function(){
      const btn = document.querySelector('.ia-mic');
      if(btn){
        btn.id = 'iaMicBtn';
        btn.onclick = window.iaMicrofono;
        iaActualizarBotonMicrofono(false);
      }
      const estado = document.getElementById('iaMicEstado');
      if(estado){
        estado.innerText = 'Primer toque: Chrome pide permiso. Elegí “Permitir mientras visito el sitio”. Después, en esta misma pestaña, el botón prende y apaga el micrófono sin volver a pedir desde el código.';
      }
    }, 50);
  };
})();
